// WebCrypto verify as jose uses it: RS256 and ES256 against fixed JWKs and
// signatures generated by node (so node and wasm agree on the same bytes).
const crypto = require('node:crypto');
const subtle = crypto.webcrypto.subtle;
const enc = new TextEncoder();
const rsaJwk = {"kty": "RSA", "n": "kUFk-LEjHF63AokX0e8efQ9b4wg3ROGK3N-0b-bO-5Ff3KQQ83a5CqcZI-JjUn-cZXl5WcotXGpLksYXre3YcadLzIPIZakf1DjxqabDOOvThhLM6gT3387BdlZIesryo-11u-RkzjVuF5ZCACBl0lmi39WRUrp8qJtc8MwU5s9swriZnea-ieNOFIA8veTlM8ZgeSCVT-r2XDfzFcT3PeAecZ81vBL4EfcZpKDaYqUYMb71FB6qfffK1XjISHi94_E7487PEj35t7xxST3xvxgoMVKRIMLgRgoR8frtwKZTyZ5oL5hJqkNnnCdxjUdeBTW8yU9-zoTBcpLzLGrLGw", "e": "AQAB"};
const ecJwk = {"kty": "EC", "x": "tZEl621OZJa6Ft3W-ztY-P53gpKud5zl5AmBZPp9ngI", "y": "5nk6GmhX5QfyqhAzj8aGjiIs1EaaMSuqyqU29bUT9r0", "crv": "P-256"};
const rsaSig = '';
const ecSig = 'd68d48524084a91cd6a65038d950c5ab712b238866ff1124d3b864ec591783c587834bf5309eb701988b3802c42b2c59587d07b33f8e49adad77fd8574600d73';
(async () => {
  const msg = enc.encode('header.payload');
  const bad = enc.encode('header.payloaX');
  const rsaKey = await subtle.importKey(
    'jwk', rsaJwk, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
  console.log('rs256', await subtle.verify('RSASSA-PKCS1-v1_5', rsaKey, Buffer.from(rsaSig, 'hex'), msg));
  console.log('rs256-bad', await subtle.verify('RSASSA-PKCS1-v1_5', rsaKey, Buffer.from(rsaSig, 'hex'), bad));
  const ecKey = await subtle.importKey(
    'jwk', ecJwk, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
  console.log('es256', await subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, ecKey, Buffer.from(ecSig, 'hex'), msg));
  console.log('es256-bad', await subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, ecKey, Buffer.from(ecSig, 'hex'), bad));
})().catch((e) => {
  console.log('error', e && e.message);
  process.exitCode = 1;
});
